import yaml

with open('tests/dotnet-ai/scan-agentic-app-perf/eval.yaml') as f:
    data = yaml.safe_load(f)

# Validate structure
assert 'scenarios' in data
for s in data['scenarios']:
    assert 'name' in s and s['name'], f'Missing name in scenario'
    assert 'prompt' in s and s['prompt'], f'Missing prompt in {s[\"name\"]}'
    assert 'timeout' in s, f'Missing timeout in {s[\"name\"]}'
    if 'assertions' in s:
        for a in s['assertions']:
            assert 'type' in a, f'Missing assertion type in {s[\"name\"]}'
    if 'setup' in s and 'files' in s['setup']:
        for f_entry in s['setup']['files']:
            assert 'path' in f_entry, f'Missing file path in {s[\"name\"]}'
            assert 'content' in f_entry or 'source' in f_entry, f'Missing content/source in {s[\"name\"]}'
    # Check prompt doesn't mention skill name
    if 'scan-agentic-app-perf' in s['prompt']:
        print(f'WARNING: prompt in {s[\"name\"]} mentions skill name')

print('All 7 scenarios validated successfully')
print(f'Categories covered: topology, history, prompt, otel, model, parallel + clean baseline')
"", "description": "Validate eval structure"}
